#include <iostream>
#include <vector>
#include <string>

struct Data {
  std::string prefix; 
  int value;
  std::string suffix;
  size_t prefixLength() const { return prefix.length(); }
};

int main() {
  std::vector<Data> data = {{"pre1", 10, "suf1"}, {"pre22", 20, "suf2"}, {"pre333", 30, "suf3"}};
  //Using iterators for maximum efficiency and control:
  long totalPrefixLength = 0;
  for (auto it = data.begin(); it != data.end(); ++it) {
    totalPrefixLength += it->prefixLength();
  }
  std::cout << "Total prefix length (iterators): " << totalPrefixLength << std::endl;
  //Using range-based for loop for conciseness (less efficient for large datasets):
  totalPrefixLength = 0;
  for (const auto& item : data) {
    totalPrefixLength += item.prefixLength();
  }
  std::cout << "Total prefix length (range-based for): " << totalPrefixLength << std::endl;
  return 0;
}
